def seed_question_bank(apps, schema_editor):
    Category = apps.get_model("core", "Category")
    QuestionTemplate = apps.get_model("core", "QuestionTemplate")
    if QuestionTemplate.objects.exists():
        return
    for index, (text, answer_type, choices, category_names, is_default) in enumerate(STARTER_QUESTIONS, start=1):
        template = QuestionTemplate.objects.create(
            text=text,
            answer_type=answer_type,
            choices=list(choices),
            is_general=not category_names,
            is_default=is_default,
            sort_order=index * 10,
        )
        if category_names:
            template.categories.set(Category.objects.filter(name__in=category_names))


def snapshot_existing_questions(apps, schema_editor):
    """Starter questions were typed by finders; mark them as free-text."""
    VerificationQuestion = apps.get_model("core", "VerificationQuestion")
    VerificationQuestion.objects.filter(answer_type="").update(answer_type="TEXT")


